import React, { createContext, useContext, useState, useEffect } from 'react';

const CartContext = createContext(null);

export const CartProvider = ({ children }) => {
  const [cart, setCart] = useState([]);

  // On app load, auto-read from localStorage
  useEffect(() => {
    const stored = localStorage.getItem('shopzone_cart');
    if (stored) setCart(JSON.parse(stored));
  }, []);

  const saveCart = (items) => {
    setCart(items);
    localStorage.setItem('shopzone_cart', JSON.stringify(items));
  };

  const addToCart = (product, qty = 1) => {
    const existing = cart.find(i => i._id === product._id);
    if (existing) {
      saveCart(cart.map(i => i._id === product._id ? { ...i, qty: i.qty + qty } : i));
    } else {
      saveCart([...cart, { ...product, qty }]);
    }
  };

  const removeFromCart = (id) => saveCart(cart.filter(i => i._id !== id));

  const updateQty = (id, qty) => {
    if (qty < 1) return removeFromCart(id);
    saveCart(cart.map(i => i._id === id ? { ...i, qty } : i));
  };

  const clearCart = () => saveCart([]);

  const cartTotal = cart.reduce((sum, i) => sum + i.price * i.qty, 0);
  const cartCount = cart.reduce((sum, i) => sum + i.qty, 0);

  return (
    <CartContext.Provider value={{ 
      cart, 
      addToCart, 
      removeFromCart, 
      updateQty, 
      clearCart, 
      cartCount, 
      cartTotal 
    }}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => useContext(CartContext);
